**Interfaces:**
- Consumes: `Offer` from Task 5; the `drive` wire message from Task 7.
- Produces:

```ts
export interface Press { from: string; run: string; seq: number; ref: string; press: string; move?: string; answer?: Record<string, unknown> }
export interface Verdict { ok: boolean; say?: string }
export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict;
```

- [ ] **Step 1: Write the failing test**

```ts
import { describe, expect, it, vi } from "vitest";
import { takePress } from "./takePress.ts";

const offer = { seq: 42, primary: { id: "roll" as const, label: "Roll", kind: "rollTable" }, moves: [{ id: "died", label: "I died" }], undo: null, needsPage: null, presets: [] };
const acts = () => ({ primary: vi.fn(), move: vi.fn(), undo: vi.fn(), answer: vi.fn() });

describe("takePress", () => {
  it("presses the primary and says so", () => {
    const act = acts();
    expect(takePress({ from: "d", run: "s1", seq: 42, ref: "r1", press: "primary" }, { seq: 42, offer, seen: new Map() }, act)).toEqual({ ok: true });
    expect(act.primary).toHaveBeenCalledTimes(1);
  });

  it("refuses a press drawn from an offer the run has moved past", () => {
    const act = acts();
    const out = takePress({ from: "d", run: "s1", seq: 41, ref: "r1", press: "primary" }, { seq: 42, offer, seen: new Map() }, act);
    expect(out).toEqual({ ok: false, say: "That moved on." });
    expect(act.primary).not.toHaveBeenCalled();
  });

  it("takes the same ref twice as one press", () => {
    const act = acts();
    const seen = new Map();
    takePress({ from: "d", run: "s1", seq: 42, ref: "r1", press: "primary" }, { seq: 42, offer, seen }, act);
    const again = takePress({ from: "d", run: "s1", seq: 42, ref: "r1", press: "primary" }, { seq: 42, offer, seen }, act);
    expect(again).toEqual({ ok: true });
    expect(act.primary).toHaveBeenCalledTimes(1);
  });

  it("refuses a move that is no longer on offer", () => {
    const act = acts();
    const out = takePress({ from: "d", run: "s1", seq: 42, ref: "r1", press: "move", move: "salvage" }, { seq: 42, offer, seen: new Map() }, act);
    expect(out).toEqual({ ok: false, say: "That is not on offer." });
    expect(act.move).not.toHaveBeenCalled();
  });

  it("refuses the primary when the offer says the page is needed", () => {
    const act = acts();
    const blocked = { ...offer, primary: null, needsPage: "Name the bowl on the page" };
    const out = takePress({ from: "d", run: "s1", seq: 42, ref: "r1", press: "primary" }, { seq: 42, offer: blocked, seen: new Map() }, act);
    expect(out).toEqual({ ok: false, say: "Name the bowl on the page" });
  });
});
```

- [ ] **Step 2: Run test to verify it fails**

Run: `npx vitest run apps/web/src/run/takePress.test.ts`
Expected: FAIL — cannot resolve `./takePress.ts`.

- [ ] **Step 3: Write the implementation**

```ts
import type { Offer } from "./offer.ts";

export interface Press {
  from: string;
  run: string;
  seq: number;
  ref: string;
  press: string;
  move?: string;
  answer?: Record<string, unknown>;
}

export interface Verdict {
  ok: boolean;
  say?: string;
}

export interface Acts {
  primary: () => void;
  move: (id: string) => void;
  undo: () => void;
  answer: (answer: Record<string, unknown>) => void;
}

/**
 * Whether a press from outside may be taken, and taking it.
 *
 * Pure, and given everything it decides on, because this is the one
 * place a run can be moved by something that is not looking at it. Two
 * rules do the work. A press names the offer it was drawn from, so one
 * made while the unit was closing cannot roll into the next unit. And a
 * press names itself, so a deck that pressed twice in a breath, or
 * retried after an answer that never arrived, moves the run once.
 */
export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict {
  const already = at.seen.get(press.ref);
  if (already) return already;

  const settle = (verdict: Verdict): Verdict => {
    at.seen.set(press.ref, verdict);
    return verdict;
  };

  if (press.seq !== at.seq) return settle({ ok: false, say: "That moved on." });

  switch (press.press) {
    case "primary": {
      if (!at.offer.primary) return settle({ ok: false, say: at.offer.needsPage ?? "There is nothing to press." });
      act.primary();
      return settle({ ok: true });
    }
    case "move": {
      const id = press.move ?? "";
      if (!at.offer.moves.some((m) => m.id === id)) return settle({ ok: false, say: "That is not on offer." });
      act.move(id);
      return settle({ ok: true });
    }
    case "undo": {
      if (!at.offer.undo) return settle({ ok: false, say: "There is nothing to take back." });
      act.undo();
      return settle({ ok: true });
    }
    case "answer": {
      if (!press.answer) return settle({ ok: false, say: "That answer was empty." });
      act.answer(press.answer);
      return settle({ ok: true });
    }
    default:
      return settle({ ok: false, say: "This run does not know that press." });
  }
}
```

