      move: (id) => run.takeMove(id),
      undo: () => run.undo(),
      answer: (a) => run.declareSubject(String(a["subject"] ?? "")),
    });
    live?.drove(news.from, news.ref, verdict.ok, verdict.say);
  });
}, [publishing, run, currentOffer, live]);
```

Hoist the `offerOf(...)` call from Task 6 into a `useMemo` named `currentOffer` so the publisher and this both read one value rather than computing it twice.

